<script setup lang="ts">
import { ref, onMounted } from 'vue'
import { ElMessage } from 'element-plus'
import { api, type Page } from './api'
const props = defineProps<{ permissions: string[] }>()
interface Line { planId: string; sourceRevision: string; orderVersion: number; quantity: string }
interface Asn { id: string; reference: string; status: string; version: number; lines: Line[] }
interface Plan { id: string; orderId: string; externalOrder: string; externalItem: string; externalSchedule: string; quantity: string; sourceRevision: string }
const receiptDetail=ref<Record<string,unknown>>(),receiptOpen=ref(false)
async function showReceipt(id:string){receiptDetail.value=await api<Record<string,unknown>>('/goods-receipts/'+id);receiptOpen.value=true}
const tab=ref('asns'), rows=ref<Asn[]>([]), total=ref(0), page=ref(1), receipts=ref<Record<string, unknown>[]>([]), receiptTotal=ref(0), receiptPage=ref(1)
const plans=ref<Plan[]>([]), planPage=ref(1), planTotal=ref(0), edit=ref(false), editId=ref(''), editVersion=ref(0), reference=ref(''), lines=ref<Line[]>([]), selected=ref(''), busy=ref(false), balances=ref<Record<string,unknown>[]>([]), balanceOpen=ref(false)
const states: Record<string,string>={DRAFT:'草稿（未占量）',SUBMITTED:'已提交（未代表收货）',CANCELLED:'已取消',SUPERSEDED:'来源改版失效'}
async function run(action:()=>Promise<void>) { if(busy.value)return;busy.value=true;try{await action()}catch(e){ElMessage.error(e instanceof Error?e.message:'操作失败')}finally{busy.value=false} }
async function load(){const v=await api<Page<Asn>>(`/asns?page=${page.value-1}`);rows.value=v.items;total.value=v.total;const r=await api<Page<Record<string,unknown>>>(`/goods-receipts?page=${receiptPage.value-1}`);receipts.value=r.items;receiptTotal.value=r.total}
async function planList(){const p=await api<Page<Plan>>(`/delivery-plans?status=OPEN&page=${planPage.value-1}`);plans.value=p.items;planTotal.value=p.total}
async function open(h?:Asn){await planList();editId.value=h?.id||'';editVersion.value=h?.version||0;reference.value=h?.reference||'';lines.value=h?h.lines.map(l=>({planId:l.planId,sourceRevision:l.sourceRevision,orderVersion:l.orderVersion,quantity:l.quantity})):[];edit.value=true}
async function add(){const p=plans.value.find(p=>p.id===selected.value);if(!p)return;if(lines.value.some(l=>l.planId===p.id)){ElMessage.warning('该计划已在草稿中');return}const o=await api<{version:number}>(`/purchase-orders/${p.orderId}`);lines.value.push({planId:p.id,sourceRevision:p.sourceRevision,orderVersion:o.version,quantity:''})}
async function save(){const h=await api<Asn>(editId.value?`/asns/${editId.value}`:'/asns',editId.value?'PUT':'POST',{reference:reference.value,lines:lines.value},editId.value?editVersion.value:undefined);edit.value=false;await load();ElMessage.success(`ASN ${h.reference} 草稿已保存`)}
async function change(h:Asn,action:string){await api(`/asns/${h.id}/${action}`,'POST',undefined,h.version);await load();ElMessage.success(action==='submit'?'ASN 已提交，实际收货仍以 ERP 为准':'ASN 已取消')}
async function balance(h:Asn){const full=await api<{lines:{orderId:string}[]}>(`/asns/${h.id}`);const orders=[...new Set(full.lines.map(l=>l.orderId))];balances.value=(await Promise.all(orders.map(id=>api<Record<string,unknown>[]>(`/purchase-orders/${id}/shipping-balances`)))).flat();balanceOpen.value=true}
onMounted(()=>run(load))
</script>
<template><section class="card"><h2>送货与实际收货</h2><el-alert title="ASN 是送货通知，不是实际收货。只有 ERP 收货及冲销会改变净收货数量。" type="info" :closable="false"/><el-tabs v-model="tab"><el-tab-pane label="ASN 送货通知" name="asns"><el-button :disabled="busy" v-if="props.permissions.includes('asn.manage')" type="primary" @click="run(()=>open())">新建 ASN 草稿</el-button><el-button :disabled="busy" @click="run(load)">刷新送货记录</el-button><el-table :data="rows"><el-table-column prop="reference" label="送货通知号"/><el-table-column label="状态"><template #default="{row}">{{states[row.status]}}</template></el-table-column><el-table-column label="行数"><template #default="{row}">{{row.lines.length}}</template></el-table-column><el-table-column label="操作" width="390"><template #default="{row}"><el-button :disabled="busy" @click="run(()=>balance(row))">数量账本</el-button><template v-if="props.permissions.includes('asn.manage')"><el-button :disabled="busy" v-if="row.status==='DRAFT'" @click="run(()=>open(row))">编辑草稿</el-button><el-button :disabled="busy" v-if="row.status==='DRAFT'" type="primary" @click="run(()=>change(row,'submit'))">提交送货</el-button><el-button :disabled="busy" v-if="['DRAFT','SUBMITTED'].includes(row.status)" @click="run(()=>change(row,'cancel'))">取消 ASN</el-button></template></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next,total" @current-change="run(load)"/></el-tab-pane><el-tab-pane label="ERP 实际收货与冲销" name="receipts"><el-button :disabled="busy" @click="run(load)">刷新实际收货</el-button><el-table :data="receipts"><el-table-column prop="external_key" label="ERP 凭证复合键" min-width="220"/><el-table-column prop="external_item" label="订单行"/><el-table-column prop="external_schedule" label="计划行"/><el-table-column label="事件"><template #default="{row}">{{row.event_type==='POSTED'?'实际收货':'收货冲销'}}</template></el-table-column><el-table-column prop="quantity" label="来源数量"/><el-table-column prop="posting_date" label="过账日期"/><el-table-column label="收货状态"><template #default="{row}">{{({POSTED:'已收货',PARTIALLY_REVERSED:'部分冲销',REVERSED:'全部冲销',REVERSAL:'冲销事件'} as Record<string,string>)[row.receipt_status]}}</template></el-table-column><el-table-column label="分配"><template #default="{row}"><el-button :disabled="busy" @click="run(()=>showReceipt(row.id))">凭证与分配</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="receiptPage" :total="receiptTotal" :page-size="20" layout="prev,pager,next,total" @current-change="run(load)"/></el-tab-pane></el-tabs></section>
<el-dialog v-model="edit" title="ASN 草稿" width="850px"><el-form label-position="top"><el-form-item label="送货通知号"><el-input v-model="reference" aria-label="送货通知号" :disabled="!!editId" placeholder="字母、数字、下划线或短横线"/></el-form-item><el-form-item label="添加交货计划"><el-select v-model="selected" aria-label="添加交货计划"><el-option v-for="p in plans" :key="p.id" :value="p.id" :label="`${p.externalOrder} / ${p.externalItem} / ${p.externalSchedule} / ${p.quantity} / ${p.id.slice(0,8)}`"/></el-select><el-pagination v-model:current-page="planPage" :total="planTotal" :page-size="20" layout="prev,pager,next" @current-change="run(planList)"/><el-button :disabled="busy" @click="run(add)">添加计划行</el-button></el-form-item><el-table :data="lines"><el-table-column prop="planId" label="交货计划"/><el-table-column prop="sourceRevision" label="来源版本"/><el-table-column label="本批送货数量"><template #default="{row}"><el-input v-model="row.quantity" aria-label="本批送货数量"/></template></el-table-column><el-table-column label="移除"><template #default="{row}"><el-button :disabled="busy" @click="lines=lines.filter(l=>l!==row)">移除行</el-button></template></el-table-column></el-table><p>草稿保存后提交才预留数量。订单变化后请移除并重新添加计划行，以确认新版本。</p><el-button :disabled="busy" type="primary" :loading="busy" @click="run(save)">保存 ASN 草稿</el-button></el-form></el-dialog>
<el-dialog v-model="balanceOpen" title="发货与实际收货数量账本" width="85%"><el-table :data="balances"><el-table-column prop="scheduleId" label="计划行标识"/><el-table-column prop="submittedQuantity" label="累计有效 ASN"/><el-table-column prop="receivedQuantity" label="ERP 净收货"/><el-table-column prop="inTransitQuantity" label="在途数量"/><el-table-column prop="availableQuantity" label="可发余额"/></el-table></el-dialog><el-dialog v-model="receiptOpen" title="ERP 凭证与 ASN 分配"><template v-if="receiptDetail"><p>凭证 {{receiptDetail.external_key}} · 数量 {{receiptDetail.quantity}}</p><p v-if="receiptDetail.original_id">原收货标识 {{receiptDetail.original_id}}</p><el-table :data="(receiptDetail.allocations as Record<string,unknown>[])"><el-table-column prop="reference" label="ASN 通知号"/><el-table-column prop="line_number" label="ASN 行号"/><el-table-column prop="quantity" label="分配数量"/></el-table><p>未分配数量仍计入 ERP 净收货，不自动消耗其他 ASN 的在途数量。</p></template></el-dialog></template>


